import React, { useEffect, useState, useRef } from 'react';
import DDBunit2 from '@/components/DDBunit/DDBunit2';
import Func from './f';
import { automaticPageDef } from '@/services/hts/api';
import assembleConfigUtil from '@/components/DDBunit/assemble_config_util';
import { Image, Card } from 'antd';
import myUtil from '@/components/DDAssist/util';
import { PlayOne } from '@icon-park/react';
import { Link } from 'umi';

const Unit2: React.FC<unknown> = () => {
  const [myConfig, setMyConfig] = useState<any>({});
  const refDDBunit2: any = useRef();

  const module_key = 'eg_m_media_video_cus';

  useEffect(() => {
    automaticPageDef(module_key).then((response1: any) => {
      if (response1.code === '200') {
        let tmpConfig = assembleConfigUtil.module.assembleAll({
          moduleInfo: response1.body.moduleInfo,
          appTableDict: response1.body.appTableDict,
        });
        // 自定义卡片示例
        tmpConfig.grid_list_card_render = (item: any) => {
          let coverTmp;
          let mediaPathPic = `${API_URL_BASE}/static/${item.mediaPathPic}.${item.mediaTypePic}`;
          let mediaPathVideo = `${API_URL_BASE}/static/${item.mediaPathVideo}.${item.mediaTypeVideo}`;
          coverTmp =<Image
            src={mediaPathPic}
            fallback="data:image/png;base64,"
          />;
          return <>
            <Card hoverable variant="borderless"
              style={{ width: '100%', position: 'relative' }}
              cover={
                coverTmp
              } >
              <Card.Meta title={item.classTitle} description={item.class_description} />
              <div style={{fontSize: '12px', margin: '14px 0 0 0', padding: '12px 0 0 0', borderTop: '1px dashed #ddd'}}>{item.class_tag}</div>
              <div style={{fontSize: '15px', margin: '4px 0 0 0', color: '#900000'}}>{`¥ ${myUtil.text.formatNum(item.class_price, '0,0.00')}`}</div>
              <div style={{fontSize: '13px', margin: '4px 0 0 0', color: '#656565'}}>{`更新 ${myUtil.date.formatDate(item.class_time, 'YYYY-MM-DD')}`}</div>
              <span style={{position: 'absolute', right: '0', bottom: '0'}}>
                <Link to={`/player?mediaPath=${mediaPathVideo}`} target='_blank' style={{display: 'block', textAlign: 'center', padding: '12px 0 0 0 '}}>
                  <PlayOne theme="outline" size='18' fill='#0a6ed1' />
                </Link>
              </span>
            </Card>
          </>
        }
        setMyConfig(tmpConfig);
      }
    });
  }, []);

  return <>
    <DDBunit2 config={myConfig} func={Func} refDDBunit2={refDDBunit2}/>
  </>;
};

export default Unit2;